using UnityEngine;
using LWS.TruckSports;
namespace LWS.TruckTerrierRacing {
public sealed class TerrierRacer:MonoBehaviour {
 public TerrierMatch match;public SportsEventTruck truck;public int slot;public bool Alive{get;private set;}public Vector3 Incoming{get;private set;}public int Jumps{get;private set;}public float LastJump{get;private set;}
 public Vector3 SweepStartCenter{get;private set;}public Quaternion SweepStartRotation{get;private set;}public float SweepStartTime{get;private set;}
 public bool OffCourse{get;private set;}public bool Creamed{get;private set;}[Min(0)]public float airLevelStrength=2.6f,airSteering=1.25f,airDamping=.8f;float airAge,impactAge=10;float cooldown,tipped,blocked,missedAge,lostMomentum,lastObstacle=-100,obstacleZ;Vector3 previous;public bool Finished{get;private set;}
 public void Finish(){Finished=true;foreach(var wheel in truck.wheels){wheel.MotorTorque=0;wheel.BrakeTorque=0;wheel.SteerAngle=0;}}public void Prepare(Vector3 p){truck.slot=slot;truck.visuals.gameObject.SetActive(true);truck.Prepare(p,match.course.DrivingRotation);truck.Power(false);truck.body.isKinematic=true;Alive=true;Finished=OffCourse=Creamed=false;Jumps=0;airAge=0;impactAge=10;cooldown=tipped=blocked=missedAge=lostMomentum=0;lastObstacle=-100;previous=p;}
 public void Release(){truck.body.isKinematic=false;truck.Power(true);}
 public bool Jump(bool requested){if(!requested||cooldown>0||!truck.Grounded||!Alive)return false;cooldown=.85f;LastJump=match.HeatTime;Jumps++;truck.body.AddForce(Vector3.up*6.2f,ForceMode.VelocityChange);match.JumpEvent(slot);match.Pulse(slot,.12f,.07f);return true;}
 public void Step(Vector2 input,bool jump,float dt){if(!Alive)return;SweepStartCenter=truck.shape.transform.TransformPoint(truck.shape.center);SweepStartRotation=truck.body.rotation;SweepStartTime=Time.fixedTime;if(Finished){foreach(var wheel in truck.wheels){wheel.MotorTorque=0;wheel.BrakeTorque=0;wheel.SteerAngle=0;}Incoming=truck.body.linearVelocity;return;}if(OffCourse){truck.Power(false);Incoming=truck.body.linearVelocity;if(match.course.Local(truck.body.position).y< -185)match.QueueWreck(slot,Time.fixedTime,"FALL_OUTSIDE_DESSERT_BASIN");return;}cooldown=Mathf.Max(0,cooldown-dt);truck.grip=1.2f*match.course.Grip(truck.body.position);truck.TickDrive(input);Jump(jump);var body=truck.body;AirControl(input,dt);body.AddForce(match.course.weather.Flow*(truck.Grounded?.15f:.55f)*Mathf.Max(0,match.course.windForceMultiplier),ForceMode.Acceleration);if(truck.Grounded){var up=body.rotation*Vector3.up;if(Vector3.Dot(up,Vector3.up)<.5f)tipped+=dt;else tipped=0;if(tipped>1)body.AddTorque(Vector3.Cross(up,Vector3.up)*4-body.angularVelocity,ForceMode.Acceleration);}if((body.position-previous).sqrMagnitude<.0001f&&input.sqrMagnitude>.1f)blocked+=dt;else blocked=Mathf.Max(0,blocked-dt);previous=body.position;Incoming=body.linearVelocity;bool failedJump=match.HeatTime-lastObstacle<3&&Mathf.Abs(match.course.Local(body.position).z-obstacleZ)<4&&Vector3.ProjectOnPlane(Incoming,Vector3.up).magnitude<2.5f;if(failedJump)missedAge+=dt;else missedAge=Mathf.Max(0,missedAge-dt*2);bool stranded=match.HeatTime>4&&(Jumps>0||match.HeatTime-lastObstacle<8)&&Incoming.sqrMagnitude<2.25f&&(Vector3.Dot(transform.up,Vector3.up)<.45f||match.HeatTime-lastObstacle<8||blocked>1);lostMomentum=stranded?lostMomentum+dt:Mathf.Max(0,lostMomentum-dt*2);if(missedAge>=1.1f||lostMomentum>=2.5f){match.QueueWreck(slot,Time.fixedTime,"MISSED_JUMP_IMMOBILE");return;}var local=match.course.Local(body.position);if(local.y< -2||Mathf.Abs(local.x)>match.course.HalfWidth(local.z)+4||local.z>match.course.Length+15){OffCourse=true;truck.Power(false);}}
 // Restrained pitch/roll damping and yaw correction; never changes linear momentum.
 void AirControl(Vector2 input,float dt){impactAge+=dt;if(truck.Grounded){airAge=0;return;}airAge+=dt;var body=truck.body;var up=body.rotation*Vector3.up;if(airAge<.1f||impactAge<.65f||Vector3.Dot(up,Vector3.up)<.25f)return;var omega=body.angularVelocity;var pitchRoll=Vector3.ProjectOnPlane(omega,Vector3.up);var torque=Vector3.Cross(up,Vector3.up)*airLevelStrength-pitchRoll*airDamping+Vector3.up*(input.x*airSteering-omega.y*.35f);body.AddTorque(Vector3.ClampMagnitude(torque,3.5f)*Mathf.Clamp01((airAge-.1f)/.2f),ForceMode.Acceleration);}
 public void LandInCream(){if(!Alive||!Finished||match.HeatWinner!=slot)return;Creamed=true;truck.Power(false);truck.StopSound();} public float Blocked=>blocked;
 public void Wreck(){if(!Alive)return;Alive=false;truck.Power(false);truck.body.detectCollisions=false;truck.body.isKinematic=true;truck.visuals.gameObject.SetActive(false);truck.StopSound();}
 void OnCollisionStay(Collision c){if(!Alive||Finished||match.Phase!=TerrierPhase.Race||c.collider.GetComponent<TerrierJumpObstacle>()==null)return;if(match.HeatTime-lastObstacle>.1f)obstacleZ=match.course.Local(truck.body.position).z;lastObstacle=match.HeatTime;}
 void OnCollisionEnter(Collision c){if(!Alive||match.Phase!=TerrierPhase.Race)return;if(c.relativeVelocity.magnitude>7.5f&&(c.collider.GetComponent<TerrierJumpObstacle>()!=null||c.collider.GetComponentInParent<TerrierRacer>()!=null))impactAge=0;if(Finished){match.finishDiagnostics?.Event(slot,"AFTER_FINISH_CONTACT_IGNORED "+c.collider.name,Time.fixedTime,match.course.TruckBounds(truck.shape));return;}if(c.collider.GetComponent<TerrierJumpObstacle>()!=null){for(int i=0;i<c.contactCount;i++)if(Mathf.Abs(c.GetContact(i).normal.z)>.25f&&Incoming.z>2.5f){lastObstacle=match.HeatTime;obstacleZ=match.course.Local(truck.body.position).z;break;}}
 var wall=c.collider.GetComponent<TerrierFinishWall>();if(wall==null||c.collider.isTrigger||!(c.collider is BoxCollider))return;var bounds=match.course.TruckBounds(truck.shape);for(int i=0;i<c.contactCount;i++){var contact=c.GetContact(i);var localPoint=match.course.Local(contact.point);var localNormal=match.course.geometry.InverseTransformDirection(contact.normal);float speed=Mathf.Max(0,-Vector3.Dot(Incoming,contact.normal));bool safe=TerrierRules.SafeTunnelSide(localPoint,localNormal,match.course.Length)||TerrierRules.SafeOpeningLip(localPoint,bounds,match.course.Length);float extent=0;var size=Vector3.Scale(truck.shape.size*.5f,truck.transform.lossyScale);extent=Mathf.Abs(Vector3.Dot(SweepStartRotation*Vector3.right,contact.normal))*size.x+Mathf.Abs(Vector3.Dot(SweepStartRotation*Vector3.up,contact.normal))*size.y+Mathf.Abs(Vector3.Dot(SweepStartRotation*Vector3.forward,contact.normal))*size.z;float gap=Mathf.Max(0,Vector3.Dot(SweepStartCenter-contact.point,contact.normal)-extent);float eventTime=SweepStartTime+Mathf.Clamp(speed>.001f?gap/speed:0,0,Time.fixedDeltaTime);bool fatal=!safe&&speed>=10.5f;match.finishDiagnostics?.Contact(slot,c.collider,localPoint,localNormal,speed,bounds,eventTime,safe?"SAFE_OPENING":fatal?"SOLID_BARRIER_IMPACT":"NONFATAL_GRAZE");if(fatal)match.QueueWreck(slot,eventTime,"SOLID_BARRIER "+c.collider.name+" normalSpeed="+speed.ToString("F3"));}}
}
}
